"""Generate the selected compiled address/backend contracts; never probe a target."""
import argparse
import json
import os
from pathlib import Path
import subprocess
import tempfile


def render(data):
    if (not isinstance(data, dict) or data.get("schema") != "kn.capabilities.v1" or
            data.get("target_probed") is not False or data.get("scope") != "compiled_contract" or "probe" in data):
        raise ValueError("only the unprobed compiled contract can generate public documentation")
    lines = [
        "# Selected source support contracts", "",
        "Generated by `tools/generate-support-matrix.py` from `--capabilities`.",
        "This is a selected compiled inventory, not a validated platform matrix.",
        "Runtime observations come from `--capabilities --probe` and remain private.",
        "The probe opens only its own process and an existing native device; it does",
        "not start a service or load a driver. Connection, sample, layout, semantics",
        "and environment validation have separate states. A successful owned read",
        "qualifies that control range only. Native connection checks stay partial.", "",
        "Address shape does not establish mapped memory, effective permissions,",
        "decoder coverage or real LA57 compatibility. `legacy_la48` is the explicit",
        "compatibility assumption for recorded inputs that declare it. Current",
        "native paths use the source descriptor where identified below; remaining",
        "collectors require their own admission/layout/decoder validation. WOW64",
        "pointer slots, VTL1, other CPU architectures and hardware execution",
        "backends are not implied by an x64 address width.", "",
        "| Domain / operation | Backend | Implementation | Address contract | Consistency |",
        "| --- | --- | --- | --- | --- |",
    ]
    seen = set()
    for item in data["capabilities"]:
        key = (item["domain"], item["operation"], item["backend"])
        if key in seen or item.get("availability") != "not_probed":
            raise ValueError("duplicate or probed capability")
        seen.add(key)
        cells = (f"{key[0]} / {key[1]}", key[2], item["implementation"],
                 item["address_contract"], item["consistency"])
        if any(not isinstance(cell, str) or "\n" in cell or "\r" in cell for cell in cells):
            raise ValueError("invalid capability cell")
        lines.append("| " + " | ".join(cell.replace("|", "\\|") for cell in cells) + " |")
    if not seen or data.get("inventory_complete") is not False:
        raise ValueError("unexpected inventory scope")
    lines += ["", "The operation's `requirements` and `limits` remain in the JSON contract.",
              "No row is a claim of a validated OS/CPU/VBS/HVCI/protected-target",
              "combination. Exact host, artifact, source, layout and regression evidence",
              "must accompany such a claim; absent checks remain unknown.", ""]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--exe", type=Path, required=True)
    parser.add_argument("--output", type=Path, default=Path(__file__).resolve().parents[1] / "docs/SUPPORT_MATRIX.md")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    try:
        run = subprocess.run([str(args.exe.resolve()), "--capabilities"], check=True,
                             capture_output=True, text=True, encoding="utf-8", timeout=30)
        content = render(json.loads(run.stdout))
        if args.check:
            if args.output.read_text(encoding="utf-8-sig") != content:
                raise ValueError("generated support matrix is stale")
        else:
            temporary = None
            try:
                with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="\n",
                                                 dir=args.output.parent, prefix=".support-matrix-",
                                                 delete=False) as stream:
                    temporary = Path(stream.name)
                    stream.write(content)
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(temporary, args.output)
                temporary = None
            finally:
                if temporary is not None:
                    temporary.unlink(missing_ok=True)
    except (OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError):
        print("Support matrix validation/generation failed; check the compiled contract and output.")
        return 1
    print("Support matrix matches compiled contracts" if args.check else "Support matrix generated")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
